<template>
  <div class="content">
    <div class="container">
      <div class="row">
        <div class="col" style="text-align: center;">
          <h2>회원가입</h2>
          <br>
          <br>
        </div>
      </div>
      <div class="row">
        <div class="col-2"></div>
        <div class="col-2">
          <label>아이디</label>
          <br>
        </div>
        <div class="col-6" style="gap: 5px;">
          <input type="text" v-model="userId" ref="userIdInput" @input="resetIdCheck" placeholder="영문,숫자 공백없이 6~12자리"
          :class="['custom-input', { 'input-error': errors.userId  }]"/>&nbsp;&nbsp;
          <button type="button" class="btn btn-dark" @click="checkUserId">아이디중복확인</button>
          <p v-if="errors.userId" class="error-text">{{ errors.userId }}</p>
          <p v-if="userId && !isDuplicate" style="color: green;">사용 가능한 아이디입니다.</p>
        </div>
        <div class="col-2"></div></div>
        
        <div class="row">
          <div class="col-2"></div>
          <div class="col-2">
            <label>비밀번호</label>
          </div>
          <div class="col-6">
            <input type="password" v-model="userPw" ref="userPwInput" placeholder="8~20자 문자,숫자,특수문자 조합"
            :class="['custom-input', { 'input-error': errors.userPw  }]"/>
            <p v-if="errors.userPw" class="error-text">{{ errors.userPw }}</p>
          </div>
          <div class="col-2"></div>
        </div>

        <div class="row">
          <div class="col-2"></div>
          <div class="col-2">
            <label>비밀번호확인</label>
          </div>
          <div class="col-6">
            <input type="password" v-model="pwCheck" ref="pwCheckInput"
            :class="['custom-input', { 'input-error': errors.pwCheck  }]"/>
            <p v-if="errors.pwCheck" class="error-text">{{ errors.pwCheck }}</p>
          </div>
          <div class="col-2"></div>
        </div>

        <div class="row">
          <div class="col-2"></div>
          <div class="col-2">
            <label>닉네임</label>
            <br>
          </div>
          <div class="col-6">
            <input type="text" v-model="nickname" ref="nicknameInput" placeholder="공백없이 5~20자"
            :class="['custom-input', { 'input-error': errors.nickname  }]"/>
            <p v-if="errors.nickname" class="error-text">{{ errors.nickname }}</p>
          </div>
          <div class="col-2"></div>
        </div>

        <div class="row">
          <div class="col-2"></div>
          <div class="col-2">
            <label>이메일</label>
          </div>
          <div class="col-6">
            <input type="email" v-model="email" ref="emailInput" placeholder="개인/회사 이메일"
            :class="['custom-input', { 'input-error': errors.email  }]"/>
            &nbsp;&nbsp;
            <button type="button" class="btn btn-dark" @click="sendAuthCode">인증번호 전송</button>
            <p v-if="errors.email" class="error-text">{{ errors.email }}</p>
          </div>
          <div class="col-2"></div>
        </div>

        <div class="row">
          <div class="col-2"></div>
          <div class="col-2">
            <label>인증번호</label>
          </div>
          <div class="col-6">
            <input type="text" v-model="authcode" ref="authcodeInput" placeholder="인증코드 6자리"
            :class="['custom-input', { 'input-error': errors.authcode  }]"/>&nbsp;&nbsp;
            <button type="button" class="btn btn-dark" @click="authcodeVerify">인증번호확인</button>&nbsp;&nbsp;
            <button type="button" class="btn btn-dark">재전송</button>
            <p v-if="errors.authcode" class="error-text">{{ errors.authcode }}</p>
            <!-- 타이머 -->
            <div v-if="timerVisible" style="margin-top: 3px;">
                <p style="font-weight: bold;">남은 시간: {{ formatTime() }}</p>
            </div>
    
            <!-- 인증 결과 메시지 -->
            <div v-if="verifyMessage" style="margin-top: 3px;">
                <p :style="{ color: verifySuccess === true ? 'blue' : verifySuccess === false ? 'red' : 'black' }">
                  {{ verifyMessage }}
                </p>
            </div>
          </div>
          <div class="col-2">
          </div>
        </div>


        <div class="row">
          <div class="col-2"></div>
          <div class="col-2">
            <label>전화번호</label>
          </div>
          <div class="col-6">
            <input type="text" id="userTel" v-model="userTel" ref="userTelInput" placeholder="숫자만 입력"
            :class="['custom-input', { 'input-error': errors.userTel  }]" maxlength="13"
            @input="formatPhoneNumber"/>
            <p v-if="errors.userTel" class="error-text">{{ errors.userTel }}</p>
          </div>
          <div class="col-2"></div>
        </div>

        <div class="row">
          <div class="col-2"></div>
          <div class="col-2">
            <label>회사인증파일</label>
          </div>
          <div class="col-6">
            <input type="file" ref="fileInput"/>
          </div>
          <div class="col-2">
          </div>
        </div>

        <div class="row">
          <div class="col-2"></div>
          <div class="col-2">
          </div>
          <div class="col-6">
            <a style="color: gray; font-size: small;">* 개인이메일 가입 시 필수 첨부</a>
          </div>
          <div class="col-2">
          </div>
        </div>

        <div class="row">
          <div class="col" style="text-align: center;">
            <br>
            <button type="button" class="btn btn-dark" @click="validateForm">회원 가입</button>
            <br>
            <br>
          </div>
        </div>
    </div>
  </div>
  </template>
  
  <script setup>
  import { ref,watch } from 'vue'
  import axios from 'axios'

  const userId = ref('')
  const userPw = ref('')
  const pwCheck = ref('')
  const nickname = ref('')
  const userTel = ref('')
  // const userFile = ref('')

  const isDuplicate = ref(false)
  const idChecked = ref(false)

  const userIdInput = ref(null)
  const userPwInput = ref(null)
  const pwCheckInput = ref(null)
  const nicknameInput = ref(null)
  const userTelInput = ref(null)
  const fileInput = ref(null)
  const emailInput = ref(null)
  const authcodeInput = ref(null)

  const email = ref('')
  const authcode = ref('')
  const verifyMessage = ref('')
  const verifySuccess = ref(null)
  const countdown = ref(300) // 5분 = 300초
  const timer = ref(null)
  const timerVisible = ref(false)

  // 아이디 중복 체크
  const checkUserId = async () => {

      let isValid = true
      
      errors.value = {
        userId : '',
      }  // 초기화
      
      const idPattern = /^[a-zA-Z0-9]{6,12}$/
      
      if (!userId.value) {
        errors.value.userId = '아이디를 입력하세요.'
        if (isValid) userIdInput.value.focus()
        isValid = false
        return
      } else if(!idPattern.test(userId.value)) {
        errors.value.userId = '영문,숫자 공백없이 6~12자리'
        console.log('아이디 :'+userId.value)
        if (isValid) userIdInput.value.focus()
        isValid = false
        return
      }

      try {
        const response = await axios.post('http://localhost:80/join/idCheck', {
          userId: userId.value 
          })
          console.log("아이디 중복체크:"+response.data);
          if(response.data === 0) { // 중복 x
            isDuplicate.value = false
            idChecked.value = true // 중복 확인 완료 시 true 설정
          } else { // 중복 o
            errors.value.userId = '중복된 아이디입니다.'
            if (isValid) userIdInput.value.focus()
            isValid = false
            return
          }
      } catch (error) {
        console.error('중복 체크 에러:', error)
      }
    }

    const errors = ref({
      userId : '',
      userPw : '',
      pwCheck : '',
      nickname : '',
      userTel : '',
      email : '',
      authcode : ''
    })

  // 아이디 입력이 변경되면 중복 확인 상태 초기화
  // 중복확인 시에만 회원가입되게끔 구현
  const resetIdCheck = () => {
    idChecked.value = false
    isDuplicate.value = false
  }

  const sendAuthCode = async () => {

    let isValid = true

    errors.value = {
      email    : ''
     }  // 초기화

    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

    if (!emailPattern.test(email.value)) {
      errors.value.email = '이메일 주소를 입력해 주세요'
      emailInput.value.focus()
      isValid = false
    }

    try {
      const response = await axios.post('http://localhost:80/join/emailsend', {
        email: email.value
      })
      alert('인증번호가 전송되었습니다.')
      console.log('응답:', response.data)

      // 인증번호 검증 시간 측정
      startTimer()
    } catch (error) {
      console.error('이메일 전송 실패:', error)
      alert('이메일 전송에 실패했습니다.')
    }

    return isValid

  }
  const startTimer = () => {
  timerVisible.value = true
  countdown.value = 180 // 3분
  clearInterval(timer?.value)
  timer.value = setInterval(() => {
      if (countdown.value > 0) {
        countdown.value--
      } else {
        clearInterval(timer.value)
      }
    }, 1000)
  }

  // 타이머 형태 (분:초)
  const formatTime = () => {
    const minutes = String(Math.floor(countdown.value / 60)).padStart(2, '0')
    const seconds = String(countdown.value % 60).padStart(2, '0')
    return `${minutes}:${seconds}`
  }

  const authcodeVerify = async () => {
    if (!authcode.value) {
        alert('인증번호를 입력하세요.')
        return
    }

    try {
      const response = await axios.post('http://localhost:80/join/authCodeVerify', {
        email : email.value,
        authcode: authcode.value
      })
      alert('인증번호가 검증되었습니다.')
      console.log('응답:', response.data)

      if (response.data === 'success') {
        verifyMessage.value = '인증번호가 확인되었습니다.'
        //인증번호 검증되면 타이머 숨기기
        timerVisible.value = false
        verifySuccess.value = true
      } else {
        verifyMessage.value = '인증번호가 일치하지 않습니다.'
        verifySuccess.value = false
      }

    } catch (error) {
      console.error('인증번호 검증 실패:', error)
      alert('인증번호 검증에 실패했습니다.')
    }
  }

  const validateForm = () => {

    let isValid = true

    errors.value = {
      userId : '',
      userPw : '',
      pwCheck : '',
      nickname : '',
      userTel : '',
      userFile : '',
      authcode : ''
     }  // 초기화

    const idPattern = /^[a-zA-Z0-9]{6,12}$/
    const pwPattern = /^(?=.*[a-zA-Z])(?=.*\d)(?=.*[\W_]).{8,20}$/
    const nicknamePattern = /^\S{5,20}$/ // 공백 없는 5~20자
    const telPattern = /^\d{3}-\d{4}-\d{4}$/ // 하이픈 포함된 전화번호
    const authcodePattern = /^(?=.*[a-zA-Z])(?=.*\d)[a-zA-Z\d]{6}$/

    if (!idPattern.test(userId.value)) {
      errors.value.userId = '영문,숫자 공백없이 6~12자리'
      if (isValid) userIdInput.value.focus()
      isValid = false
    }
    if (!idChecked.value) {
      alert('아이디 중복 확인을 해주세요.')
      return false
    }

    if (!pwPattern.test(userPw.value)) {
      errors.value.userPw = '8~20자 문자,숫자,특수문자 조합'
      if (isValid) userPwInput.value.focus()
      isValid = false
    }

    if (userPw.value !== pwCheck.value) {
      errors.value.pwCheck = '비밀번호 불일치'
      if (isValid) pwCheckInput.value.focus()
      isValid = false
    }

    if (!nicknamePattern.test(nickname.value)) {
      errors.value.nickname = '닉네임은 공백 없이 5~20자여야 합니다.'
      if (isValid) nicknameInput.value.focus()
      isValid = false
    }

    if (!telPattern.test(userTel.value)) {
      errors.value.userTel = '전화번호 11자리를 입력하세요.'
      if (isValid) userTelInput.value.focus()
      isValid = false
    }

    if (!authcode.value) {
      errors.value.authcode = '인증번호를 입력해주세요.'
      if (isValid) authcodeInput.value.focus()
      isValid = false
    } else if(!authcodePattern.test(authcode.value)) {
      errors.value.authcode = '인증코드 6자리를 입력하세요.'
      if (isValid) authcodeInput.value.focus()
      isValid = false
    }

    return isValid
  }

  // 전화번호 입력 시 자동 하이픈
  // watch(userTel, (newVal) => {
  //   let raw = newVal.replace(/[^0-9]/g, '').slice(0, 11)
  //   if (raw.length >= 11) {
  //     userTel.value = `${raw.slice(0, 3)}-${raw.slice(3, 7)}-${raw.slice(7, 11)}`
  //   } else if (raw.length >= 7) {
  //     userTel.value = `${raw.slice(0, 3)}-${raw.slice(3, 7)}-${raw.slice(7)}`
  //   } else if (raw.length >= 4) {
  //     userTel.value = `${raw.slice(0, 3)}-${raw.slice(3)}`
  //   } else {
  //     userTel.value = raw
  //   }
  // })

  const formatPhoneNumber = (e) => {
    let raw = e.target.value.replace(/\D/g, '').slice(0,11)
    if (raw.length >= 11) {
      userTel.value = `${raw.slice(0, 3)}-${raw.slice(3, 7)}-${raw.slice(7, 11)}`
    } else if (raw.length >= 7) {
      userTel.value = `${raw.slice(0, 3)}-${raw.slice(3, 7)}-${raw.slice(7)}`
    } else if (raw.length >= 4) {
      userTel.value = `${raw.slice(0, 3)}-${raw.slice(3)}`
    } else {
      userTel.value = raw
    }
  }

  // 입력창에 데이터 입력 시 경고창 삭제
  watch(userId, () => {
    errors.value.userId = ''
  })
  watch(userPw, () => {
    errors.value.userPw = ''
  })
  watch(pwCheck, () => {
    errors.value.pwCheck = ''
  })
  watch(nickname, () => {
    errors.value.nickname = ''
  })
  watch(userTel, () => {
    errors.value.userTel = ''
  })
  watch(email, () => {
    errors.value.email = ''
  })
  watch(authcode, () => {
    errors.value.authcode = ''
  })
  
  </script>
  
  <style scoped>
  .sidebar {
  width: 200px;
  padding-right: 40px;
  border-right: 1px solid #ddd;
}

.sidebar h1 {
  font-size: 28px;
  margin-bottom: 20px;
}

.sidebar h2 {
  font-size: 20px;
  margin-bottom: 10px;
}

.sidebar h3 {
  font-size: 16px;
  color: #666;
}

.main-content {
  flex: 1;
  padding-left: 40px;
}

.row {
  gap: 23px 43px;
}

.row2 {
  gap: 23px 43px;
  /* margin-top: 4px;
  margin-bottom: 4px; */
}

.form-group {
  display: flex;
  flex-direction: column;
}

label {
  margin-bottom: 8px;
  font-weight: bold;
}

input[type="text"],
input[type="email"],
input[type="date"],
input[type="number"],
input[type="password"] {
  padding: 8px;
  border: 1px solid #ccc;
  border-radius: 4px;
}

.change-password-btn,
.company-change-btn {
  margin-top: 8px;
